package privacy
import("testing";"time";"path/filepath";"errors")
func TestReviewV4FsyncPaths(t *testing.T){for _,op:=range []string{"put","delete","update"}{for _,stage:=range []string{"sync","dirsync"}{t.Run(op+"/"+stage,func(t *testing.T){path:=filepath.Join(t.TempDir(),"p.json");p,e:=OpenPrefStore(path);if e!=nil{t.Fatal(e)};p.Put(Preferences{AccountID:"a",Source:"old"},time.Now());p.writeFault=func(s string)error{if s==stage{return errors.New("synthetic sync failure")};return nil};switch op{case "put":e=p.Put(Preferences{AccountID:"a",Source:"new"},time.Now());case "delete":e=p.Delete("a");case "update":e=p.Update("a",nil,nil,nil,"new",time.Now())};if e==nil{t.Fatal("error swallowed")};r,e2:=OpenPrefStore(path);if e2!=nil{t.Fatal(e2)};want:="old";if stage=="dirsync"{want="new";if op=="delete"{want=""};var c *prefsCommittedError;if !errors.As(e,&c){t.Fatal("missing committed uncertainty")}};if p.Get("a").Source!=want||r.Get("a").Source!=want{t.Fatal("memory/disk mismatch")};matches,_:=filepath.Glob(filepath.Join(filepath.Dir(path),".privacy-prefs-*"));if len(matches)!=0{t.Fatal("temp left")}})}}}
